<script setup lang="ts">
import { ArrowLeftRight, BadgeDollarSign, BookOpen, BriefcaseBusiness, Calculator, CarFront, ChevronDown, FileText, Hotel, Inbox, Images, Landmark, LayoutDashboard, MapPin, MapPinned, MessageSquareHeart, Newspaper, Plane, Settings, Users, CalendarRange, House, Menu, X } from 'lucide-vue-next'
const route=useRoute(),isOpen=ref(false);type Item={label:string;to:string;icon:any;section?:string};const tourMenu:Item[]=[{label:'Dashboard',to:'/tour',icon:LayoutDashboard},{label:'Leads',to:'/leads',icon:Users},{label:'Estimations',to:'/estimations',icon:Calculator},{label:'Hotels',to:'/hotels',icon:Hotel},{label:'Flights',to:'/flights',icon:Plane},{label:'Transport',to:'/transport',icon:CarFront},{label:'Services',to:'/services',icon:BriefcaseBusiness},{label:'Pricing',to:'/pricing',icon:BadgeDollarSign},{label:'Pricing Periods',to:'/pricing-periods',icon:CalendarRange},{label:'Exchange Rates',to:'/exchange-rates',icon:ArrowLeftRight},{label:'Departure Cities',to:'/departure-cities',icon:MapPin},{label:'Settings',to:'/settings',icon:Settings}];const mediaMenu:Item[]=[{label:'Dashboard',to:'/media',icon:LayoutDashboard},{label:'Home',to:'/media/settings/home',icon:House,section:'PAGE SETTINGS'},{label:'Makkah',to:'/media/settings/makkah',icon:MapPinned},{label:'Madinah',to:'/media/settings/madinah',icon:Landmark},{label:'Kontribusi Pengguna',to:'/media/contributions',icon:Inbox,section:'INTERAKSI'},{label:'Feedback Artikel',to:'/media/article-feedback',icon:MessageSquareHeart},{label:'Artikel',to:'/media/articles',icon:Newspaper,section:'CONTENT LIBRARY'},{label:'Panduan',to:'/media/guides',icon:BookOpen},{label:'Gallery',to:'/media/gallery',icon:Images},{label:'Map Locations',to:'/media/locations',icon:MapPin}];const menu=computed(()=>route.path==='/media'||route.path.startsWith('/media/')?mediaMenu:tourMenu);const activeTo=computed(()=>{const matches=menu.value.filter(x=>x.to==='/'?route.path==='/':route.path===x.to||route.path.startsWith(`${x.to}/`));return matches.sort((a,b)=>b.to.length-a.to.length)[0]?.to});watch(()=>route.fullPath,()=>{isOpen.value=false})
</script>
<template><button type="button" class="fixed left-4 top-4 z-50 flex h-11 w-11 items-center justify-center rounded-xl bg-brand-green text-white shadow-lg lg:hidden" aria-label="Buka menu admin" :aria-expanded="isOpen" @click="isOpen=!isOpen"><Menu v-if="!isOpen" class="h-5 w-5"/><X v-else class="h-5 w-5"/></button><div v-if="isOpen" class="fixed inset-0 z-30 bg-neutral-charcoal/40 lg:hidden" @click="isOpen=false"/><aside class="fixed inset-y-0 left-0 z-40 flex w-64 -translate-x-full flex-col border-r border-neutral-line bg-white transition-transform lg:translate-x-0" :class="{'translate-x-0':isOpen}"><div class="flex h-16 items-center gap-2.5 border-b border-neutral-line px-5"><div class="flex h-9 w-9 items-center justify-center rounded-xl bg-kabah-gradient text-sm font-bold text-gold-soft">S</div><div class="leading-tight"><p class="font-heading text-sm font-semibold text-brand-green">Sudut Haramain</p><p class="text-[10px] font-medium uppercase tracking-[0.22em] text-gold">Admin</p></div></div><nav class="flex-1 overflow-y-auto p-3"><template v-for="(item,index) in menu" :key="item.label"><p v-if="item.section&& (index===0||menu[index-1].section!==item.section)" class="mb-2 mt-5 px-3 text-[10px] font-semibold uppercase tracking-[0.18em] text-neutral-charcoal/45">{{item.section}}</p><NuxtLink :to="item.to" class="mb-0.5 flex items-center gap-3 rounded-xl px-3.5 py-2.5 text-sm font-medium transition-colors" :class="activeTo===item.to?'bg-sht-olive-dark text-white hover:bg-sht-olive-dark hover:text-white':'text-neutral-charcoal/70 hover:bg-sht-olive/5 hover:text-sht-olive'"><component :is="item.icon" class="h-[18px] w-[18px] shrink-0"/><span class="min-w-0 flex-1">{{item.label}}</span></NuxtLink></template></nav><div class="border-t border-neutral-line p-4"><p class="text-xs text-neutral-charcoal/50">v0.2.0 — M2 backend foundation</p></div></aside></template>
